import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  random,
  Sequence,
} from '../remotionShim';
import { noise2D } from "@remotion/noise";
import { evolvePath } from "@remotion/paths";

{/* Start Google Fonts Loader - kept for template compliance even if no text is strictly requested */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type FactoryNeuralNetworkProps = Record<string, any>;

// -- Helpers --

// Generate deterministic random nodes
const generateNodes = (count: number, width: number, height: number, seedString: string) => {
  return new Array(count).fill(0).map((_, i) => {
    const x = random(`${seedString}-x-${i}`) * width;
    const y = random(`${seedString}-y-${i}`) * height;
    // Bias towards center initially? No, let's distribute evenly.
    return { id: i, x, y };
  });
};

const FactoryNeuralNetwork: React.FC<FactoryNeuralNetworkProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 12,
  factoryLineColor = "#FFFFFF",
  emeraldColor = "#00936b",
  cyanColor = "#00fbff",
  nodeColor = "#00fbff",
  nodeCount = 60,
  connectionThreshold = 200,
}) => {
  useFontLoader(["Inter"]); // Just in case

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Colors
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // -- ANIMATION TIMING --
  // 1. Trace Factory: 0s -> 3s
  // 2. Pulse: 2.5s -> 4.5s
  // 3. Dissolve Factory: 4s -> 5s
  // 4. Reveal Network: 4s -> End

  const traceDuration = 3 * fps;
  const pulseStart = 2.5 * fps;
  const dissolveStart = 4 * fps;
  const dissolveDuration = 1.5 * fps;
  const networkStart = 3.5 * fps;

  // -- FACTORY PATH LOGIC --
  // Define a minimalist factory path (relative 0-100 coords, scaled later)
  // Sawtooth roof + chimney
  const pathDataRelative = `
    M 10,90 
    L 10,40 
    L 30,20 
    L 30,40 
    L 50,20 
    L 50,40 
    L 70,20 
    L 70,40
    L 80,40
    L 80,10
    L 90,10
    L 90,90
    Z
  `;

  // Scale path to screen
  // We want it in lower third.
  const factoryWidth = width * 0.25;
  const scale = factoryWidth / 100;
  // Centered horizontally, positioned lower Y
  const factoryX = (width - factoryWidth) / 2;
  const factoryY = height * 0.6; 
  
  // Create the actual path string with transforms
  // Simple regex replacement to scale isn't robust, so we use SVG transform in render
  
  const traceProgress = spring({
    frame,
    fps,
    config: { damping: 200, mass: 2 }, // Slow linear-ish feel
    durationInFrames: traceDuration,
  });

  const { strokeDasharray, strokeDashoffset } = evolvePath(traceProgress, pathDataRelative);

  // Pulse Logic
  const pulseProgress = interpolate(frame, [pulseStart, pulseStart + 2 * fps], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  // The pulse moves UP from the factory base
  const pulseY = interpolate(pulseProgress, [0, 1], [factoryY + 100, 0]);
  const pulseOpacity = interpolate(pulseProgress, [0, 0.2, 0.8, 1], [0, 1, 0.5, 0]);
  const pulseScale = interpolate(pulseProgress, [0, 1], [0.5, 2]);

  // Factory Dissolve
  const factoryOpacity = interpolate(
    frame,
    [dissolveStart, dissolveStart + dissolveDuration],
    [1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // -- NEURAL NETWORK LOGIC --
  const nodes = useMemo(() => {
    return generateNodes(nodeCount, width, height, "neural-net-v1");
  }, [nodeCount, width, height]);

  const networkOpacity = interpolate(
    frame,
    [networkStart, networkStart + 2 * fps],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Calculate dynamic node positions with noise
  const currentNodes = nodes.map((node) => {
    // Noise for organic floating
    const xNoise = noise2D("seed-x", node.x, frame * 0.005) * 50;
    const yNoise = noise2D("seed-y", node.y, frame * 0.005) * 50;
    
    // Expansion effect: nodes start clumped near factory, then expand
    // Calculate vector from factory center
    const centerX = width / 2;
    const centerY = height * 0.7; // Approx factory center
    const dx = node.x - centerX;
    const dy = node.y - centerY;
    
    // Expansion factor (0 = clumped, 1 = full spread)
    const expansion = interpolate(
      frame,
      [networkStart, networkStart + 3 * fps],
      [0.1, 1],
      { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: (t) => t * (2 - t) } // EaseOutQuad
    );

    return {
      id: node.id,
      x: centerX + dx * expansion + xNoise,
      y: centerY + dy * expansion + yNoise,
    };
  });

  // Calculate lines
  // Optimization: Only compute for active network to save frames early on
  const renderLines = frame > networkStart;
  const lines: React.ReactNode[] = [];

  if (renderLines) {
    for (let i = 0; i < currentNodes.length; i++) {
      for (let j = i + 1; j < currentNodes.length; j++) {
        const n1 = currentNodes[i];
        const n2 = currentNodes[j];
        const dist = Math.sqrt((n1.x - n2.x) ** 2 + (n1.y - n2.y) ** 2);

        if (dist < connectionThreshold) {
          const opacity = (1 - dist / connectionThreshold) * networkOpacity;
          if (opacity > 0.05) {
            lines.push(
              <line
                key={`${n1.id}-${n2.id}`}
                x1={n1.x}
                y1={n1.y}
                x2={n2.x}
                y2={n2.y}
                stroke={cyanColor}
                strokeWidth={1}
                strokeOpacity={opacity * 0.6}
              />
            );
          }
        }
      }
    }
  }

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 1. NEURAL NETWORK LAYER (Behind) */}
      <AbsoluteFill style={{ opacity: networkOpacity }}>
         <svg width={width} height={height} style={{ position: "absolute", top: 0, left: 0 }}>
            {/* Lines first */}
            {lines}
            {/* Nodes on top */}
            {currentNodes.map((node, i) => (
              <circle
                key={node.id}
                cx={node.x}
                cy={node.y}
                r={i % 3 === 0 ? 4 : 2} // Vary size slightly
                fill={i % 2 === 0 ? emeraldColor : nodeColor}
                opacity={0.8}
              />
            ))}
         </svg>
      </AbsoluteFill>

      {/* 2. PULSE EFFECT LAYER */}
      {pulseProgress > 0 && pulseProgress < 1 && (
         <AbsoluteFill 
            style={{
                justifyContent: 'center',
                alignItems: 'center',
                opacity: pulseOpacity,
                mixBlendMode: 'screen', // Make it glow
            }}
         >
            {/* Radial Gradient Glow */}
            <div
                style={{
                    width: width * 0.8,
                    height: width * 0.8, // Circle
                    borderRadius: '50%',
                    background: `radial-gradient(circle, ${cyanColor} 0%, ${emeraldColor} 40%, transparent 70%)`,
                    transform: `translateY(${pulseY - height/2}px) scale(${pulseScale})`,
                    filter: 'blur(40px)',
                }}
            />
         </AbsoluteFill>
      )}

      {/* 3. FACTORY ICON LAYER */}
      <AbsoluteFill 
        style={{ 
            justifyContent: "center", 
            alignItems: "center",
            opacity: factoryOpacity
        }}
      >
        <div style={{
            transform: `translate(0, ${height * 0.15}px)`, // Push to lower third manually
        }}>
            <svg
                width={factoryWidth}
                height={factoryWidth} // Square aspect for the SVG container
                viewBox="0 0 100 100"
                style={{ overflow: "visible" }}
            >
                {/* Glow Filter */}
                <defs>
                    <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                        <feGaussianBlur stdDeviation="2" result="coloredBlur" />
                        <feMerge>
                            <feMergeNode in="coloredBlur" />
                            <feMergeNode in="SourceGraphic" />
                        </feMerge>
                    </filter>
                    
                    <linearGradient id="lineGradient" x1="0%" y1="100%" x2="0%" y2="0%">
                        <stop offset="0%" stopColor={emeraldColor} />
                        <stop offset="50%" stopColor={factoryLineColor} />
                        <stop offset="100%" stopColor={cyanColor} />
                    </linearGradient>
                </defs>

                {/* The Factory Path */}
                <path
                    d={pathDataRelative}
                    stroke="url(#lineGradient)"
                    strokeWidth="1.5" // Thin 1.5px relative to 100px viewBox is ~6px on screen? No.
                    // Let's adjust stroke width. ViewBox is 100, width is ~400. 
                    // 1px screen = 0.25px SVG units.
                    // User asked for "thin, 1px white line".
                    // 1px on screen approx 0.25 in this viewBox.
                    strokeDasharray={strokeDasharray}
                    strokeDashoffset={strokeDashoffset}
                    fill="transparent"
                    style={{
                        strokeWidth: 0.3, // ~1.2px on screen
                        filter: "url(#glow)"
                    }}
                />
            </svg>
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default FactoryNeuralNetwork;